 "content": "def transform(grid):
    """Recolor the longest straight non-background run carrying a marker."""
    h = len(grid)
    w = max(map(len, grid))
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    candidates = []
    # A singleton pixel of an object color, adjacent to the background,
    # marks a same-color straight run elsewhere in the grid.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == bg or counts[color] < 2:
                continue
            if any(0 <= rr < h and 0 <= cc < len(grid[rr]) and grid[rr][cc] == bg
                   for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                # Search maximal horizontal and vertical runs of this color.
                for dr, dc in ((0,1),(1,0)):
                    cells = [(r,c)]
                    rr, cc = r-dr, c-dc
                    while 0 <= rr < h and 0 <= cc < len(grid[rr]) and grid[rr][cc] == color:
                        cells.insert(0,(rr,cc)); rr-=dr; cc-=dc
                    rr, cc = r+dr, c+dc
                    while 0 <= rr < h and 0 <= cc < len(grid[rr]) and grid[rr][cc] == color:
                        cells.append((rr,cc)); rr+=dr; cc+=dc
                    if len(cells) >= 2:
                        candidates.append((len(cells), color, cells))
    if not candidates:
        return [row[:] for row in grid]
    _, color, cells = max(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
    # The recolor is the most common non-background color in the grid
    # that is not the marked object's color.
    palette_counts = sorted(((n,v) for v,n in counts.items() if v != bg and v != color), reverse=True)
    replacement = palette_counts[0][1] if palette_counts else bg
    for r,c in cells:
        out[r][c] = replacement
    return out

